          "property_id": "PROP-W6B15-6",
          "title": "Verify Trust Boundary Integrity for tb-006: Is the authorizer's nonce incremented after successful EIP-7702 authorization processing?",
          "severity": "Critical",
          "mindset": "Boundary Guard",
