          "property_id": "PROP-W6B15-6",
          "title": "Verify EIP-7702 Authorization Replay Protection: Can the same authorization be accepted twice?",
          "severity": "Critical",
          "mindset": "Boundary Guard",
          "is_boundary_check": true,
          "reachability": {
            "classification": "external-reachable",
            "entry_points": [
              "Transaction"
            ],
            "attacker_controlled": true,
            "validation_layers": [
              "Transaction validation",
              "State transition"
            ],
            "bug_bounty_scope": "in-scope",
            "notes": "If the nonce is not incremented after authorization, the same authorization can be replayed."
          },
          "test_procedure": "1. Create and submit a valid EIP-7702 authorization.\n2. Verify the authorization is processed successfully.\n3. Immediately attempt to resubmit the identical authorization.\n4. Verify the second submission is rejected due to stale nonce.\n5. Test race conditions by submitting two identical authorizations concurrently.\n6. Verify only one succeeds and the nonce increment prevents the duplicate.",
          "bug_class": "Replay Attack",
          "risk_category": "Tampering",
          "notes": "Source: PROP-W6B15-6, Replay protection verification"
        },
